FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND upper(island) AS isle |> AGGREGATE count(*) AS penguins GROUP BY isle |> AS aggregates |> LEFT OUTER JOIN (FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND upper(island) AS isle |> EXTEND bin(body_mass_g) OVER () AS body_mass_g_bin |> AGGREGATE count(*) AS n GROUP BY isle, body_mass_g_bin |> AGGREGATE bar(x => scaled(body_mass_g_bin, title => 'body_mass_g'), y => scaled(n, title => 'count(*)')) AS chart GROUP BY isle) AS charts ON aggregates.isle IS NOT DISTINCT FROM charts.isle |> SELECT aggregates.isle, charts.chart, aggregates.penguins |> ORDER BY isle
